import { fmtDate } from "@/lib/format";
import { defaultFields, fieldCode, fieldRole, formatCell } from "./fields";
import type { SourceColumn, SourceIngest, SourceSnapshotSummary } from "./schema";

/** Label only the original-count suffix generated by prepare-official-sources.py. */
export function sourceDescription(description: string): string {
  return description.replace(
    / Retained table: (0|[1-9]\d{0,2}(?:,\d{3})*) source rows and (0|[1-9]\d{0,2}(?:,\d{3})*) columns\.(?![\s\S])/,
    " Original collection: $1 source rows and $2 columns.",
  );
}

export type SourceCoverageException = {
  key: string;
  label: string;
  values: string[];
  policyKey: string;
  policy: string | null;
};

/** Only the source's explicit exception lists are shown; counts never imply missing identities. */
export function sourceCoverageExceptions(
  coverage: Record<string, unknown>,
): SourceCoverageException[] {
  const declarations = [
    {
      key: "missing_certificates",
      label: "Missing certificates (CERT)",
      policyKey: "missing_institution_policy",
    },
    {
      key: "requested_but_not_returned_fields",
      label: "Requested fields not returned",
      policyKey: "omitted_field_policy",
    },
  ];
  return declarations.flatMap((declaration) => {
    const values = coverage[declaration.key];
    if (
      !Array.isArray(values) ||
      !values.length ||
      !values.every((value) => typeof value === "string")
    )
      return [];
    const policy = coverage[declaration.policyKey];
    return [
      { ...declaration, values: [...values], policy: typeof policy === "string" ? policy : null },
    ];
  });
}

/** Manifest keys may be positional (col0001); label retains the exact native header. */
export const nativeColumnCode = fieldCode;

/**
 * Right-aligned and grouped only where the dictionary states a quantity: a numeric native type
 * and a unit that is a quantity (`fieldRole`). Dates, codes and identifiers typed number
 * (FDIC CALLYMD "20260630", MSA "18140.0", CERT) stay exactly as published (rev-app M1).
 */
export const numericColumn = (c: SourceColumn) => fieldRole(c) === "quantity";

/**
 * Formats strings without a floating-point round trip, scaling, or treating a reported zero as
 * absent. Missing is an en dash; an empty cell shows as "" so it never looks missing.
 */
export function formatNativeValue(value: string | null | undefined, column: SourceColumn): string {
  if (value == null) return "–";
  if (value === "") return '""';
  return formatCell(value, fieldRole(column), column).text;
}

/**
 * A narrow initial table without any publisher's field names (rev-app S12): the snapshot's
 * declared dimension fields, then quantities, then file order. Every native column remains
 * available in the field picker and record detail. A profile's own choice goes through
 * `defaultFields(columns, ingest, { lead })`.
 */
export function defaultSourceColumns(
  columns: SourceColumn[],
  limit = 8,
  ingest?: Pick<SourceIngest, "dimensions" | "composites"> | null,
): number[] {
  return defaultFields(columns, ingest, { limit });
}

export function filterSourceColumns(
  columns: SourceColumn[],
  search: string,
): { column: SourceColumn; index: number }[] {
  const needle = search.trim().toLocaleLowerCase();
  return columns
    .map((column, index) => ({ column, index }))
    .filter(
      ({ column }) =>
        !needle ||
        `${column.key} ${column.label} ${column.title ?? ""} ${column.description ?? ""} ${column.unit ?? ""}`
          .toLocaleLowerCase()
          .includes(needle),
    );
}

export function sourceAvailability(snapshot: SourceSnapshotSummary | null | undefined): {
  label: string;
  tone: "quiet" | "pending" | "warning" | "ready";
  ready: boolean;
} {
  if (!snapshot) return { label: "Registered", tone: "quiet", ready: false };
  if (snapshot.status === "failed")
    return { label: "Needs attention", tone: "warning", ready: false };
  if (snapshot.status !== "ready") return { label: "Loading", tone: "pending", ready: false };
  return { label: "Ready", tone: "ready", ready: true };
}

export function safeSourceHref(value: string | null | undefined): string | null {
  if (!value) return null;
  try {
    const url = new URL(value);
    return url.protocol === "https:" || url.protocol === "http:" ? url.href : null;
  } catch {
    return null;
  }
}

/** A stored timestamp as the app writes dates ("Nov 25, 2026"); anything else as stored. */
export function sourceDate(value: string | null | undefined): string {
  if (!value) return "–";
  const day = value.slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(day) ? fmtDate(day) : value;
}

const SECTOR_NAMES: Record<string, string> = {
  financials: "Financials",
  real_estate: "Real estate",
  healthcare: "Healthcare",
  health_care: "Healthcare",
  energy: "Energy",
  utilities: "Utilities",
  industrials: "Industrials",
  materials: "Materials",
  consumer_discretionary: "Consumer discretionary",
  consumer_staples: "Consumer staples",
  information_technology: "Information technology",
  technology: "Technology",
  communication_services: "Communication services",
  sec_company_financials: "Company financials",
  ir_integration: "IR integration",
  universal: "Universal",
  communications: "Communications",
  macro: "Macro",
  source_atlas: "Source atlas",
};
export function sourceSectorName(value: string): string {
  const key = value.replace(/^\d+[_\s-]+/, "").toLowerCase();
  return SECTOR_NAMES[key] || key.replace(/[_-]+/g, " ").replace(/^\w/, (c) => c.toUpperCase());
}

export function nativeUnit(column: SourceColumn): string {
  return [column.unit, column.period_basis ?? column.basis].filter(Boolean).join(" · ");
}

/** Only declared, bounded facets are used; the explorer never guesses missing source periods. */
export function sourcePeriods(coverage: Record<string, unknown>): string[] {
  const periods = coverage.periods;
  return Array.isArray(periods) && periods.length <= 250
    ? periods.filter((p): p is string => typeof p === "string")
    : [];
}
